def player_photo_b64(name):
    """Devuelve la foto del jugador si está dentro de los 26 convocados oficiales."""
    try:
        key = canonical_key_from_name(name)
    except Exception:
        key = clean_key(name)
    if key in PLAYER_PHOTOS_B64:
        return PLAYER_PHOTOS_B64[key]
    simple = clean_key(name)
    if simple in PLAYER_PHOTOS_B64:
        return PLAYER_PHOTOS_B64[simple]
    # Fallback por apellido / parte del nombre
    for k, v in PLAYER_PHOTOS_B64.items():
        if k and (k in simple or simple in k):
            return v
    return None


