# =====================================================
# HELPERS
# =====================================================
def strip_accents(text):
    if pd.isna(text):
        return ""
    text = str(text)
    text = unicodedata.normalize("NFKD", text)
    text = "".join([c for c in text if not unicodedata.combining(c)])
    return text


def clean_key(text):
    text = strip_accents(text).lower().strip()
    text = text.replace(".", "")
    text = re.sub(r"[^a-z0-9 ]", "", text)
    text = re.sub(r"\s+", " ", text)
    return text


def to_number(series):
    return pd.to_numeric(series, errors="coerce")


def safe_str(series):
    return series.fillna("").astype(str)


def score_from_contains(value, mapping, default=0):
    value = strip_accents(value).lower()
    for pattern, score in mapping.items():
        if pattern.lower() in value:
            return score
    return default


def normalize_market_value(value):
    try:
        value = float(value)
    except Exception:
        return 0.0
    if pd.isna(value):
        return 0.0
    # Si viene en millones tipo 8, lo convertimos a euros aproximados
    if 0 < value < 500:
        value = value * 1_000_000
    return max(0.0, value)


def primary_specific_position(value):
    """Devuelve una posición específica simple: ST, LW, RW, CAM, CM, DM, CB, LB, RB, GK..."""
    if pd.isna(value):
        return "Unknown"
    text = strip_accents(str(value)).upper().replace(" ", "")
    parts = re.split(r"[,/;-]+", text)
    parts = [p.strip() for p in parts if p.strip()]
    if not parts:
        return "Unknown"

    priority = [
        "GK", "ST", "CF", "LW", "RW", "CAM", "AM", "CM", "DM", "CDM", "LM", "RM",
        "CB", "LCB", "RCB", "LB", "RB", "LWB", "RWB"
    ]
    for p in priority:
        if p in parts:
            if p in ["LCB", "RCB"]:
                return "CB"
            if p == "CDM":
                return "DM"
            if p == "AM":
                return "CAM"
            return p

    joined = " ".join(parts)
    if any(x in joined for x in ["GOALKEEPER", "PORTERO", "POR"]):
        return "GK"
    if any(x in joined for x in ["STRIKER", "FORWARD", "ATTACKER"]):
        return "ST"
    if "WINGER" in joined:
        return "LW"
    if "DEFENSIVE MIDFIELDER" in joined:
        return "DM"
    if "ATTACKING MIDFIELDER" in joined:
        return "CAM"
    if "MIDFIELDER" in joined:
        return "CM"
    if "CENTRE" in joined or "CENTER" in joined or "DEFENDER" in joined:
        return "CB"
    return parts[0]


def position_group(pos, specific=None):
    p = strip_accents(str(pos)).upper().strip()
    s = strip_accents(str(specific)).upper().strip()
    text = f"{p} {s}"
    if any(x in text for x in ["GK", "GOALKEEPER", "PORTERO", "POR"]):
        return "Goalkeeper"
    if any(x in text for x in ["ST", "CF", "FW", "LW", "RW", "WINGER", "FORWARD", "ATTACKER", "STRIKER"]):
        return "Attacker"
    if any(x in text for x in ["CM", "DM", "CDM", "CAM", "AM", "MIDFIELDER", "LM", "RM"]):
        return "Midfielder"
    if any(x in text for x in ["CB", "LB", "RB", "LWB", "RWB", "DEFENDER", "CENTRE", "CENTER", "FULLBACK", "FULL BACK"]):
        return "Defender"
    return "Unknown"


