def canonical_name_from_key(key, original_name):
    return CANONICAL_NAMES.get(key, original_name)


def canonical_key_from_name(name):
    key = clean_key(name)
    canonical = CANONICAL_NAMES.get(key)
    return clean_key(canonical) if canonical else key


def league_bonus(league):
    return score_from_contains(league, LEAGUE_LEVEL, default=3)


def club_bonus(team):
    team_clean = strip_accents(team).lower()
    return 4 if any(club in team_clean for club in BIG_CLUBS) else 0


def age_score(age):
    try:
        age = float(age)
    except Exception:
        return 4
    if pd.isna(age):
        return 4
    if age <= 20:
        return 8
    if age <= 23:
        return 7
    if age <= 26:
        return 6
    if age <= 29:
        return 4
    if age <= 32:
        return 2
    return 1


def potential_from_age(age):
    try:
        age = float(age)
    except Exception:
        return 70
    if pd.isna(age):
        return 70
    if age <= 18: return 92
    if age == 19: return 91
    if age == 20: return 90
    if age == 21: return 89
    if age == 22: return 88
    if age == 23: return 86
    if age == 24: return 84
    if age == 25: return 82
    if age == 26: return 80
    if age == 27: return 77
    if age == 28: return 74
    if age == 29: return 70
    if age == 30: return 68
    if age == 31: return 66
    return 64


def is_top5_league(league):
    league_clean = strip_accents(str(league)).lower()
    return any(x in league_clean for x in ["premier", "la liga", "primera division", "bundesliga", "serie a", "ligue 1"])


def dataset_context(row):
    txt = f"{row.get('league','')} {row.get('dataset','')}".lower()
    txt = strip_accents(txt)
    if "botola" in txt:
        return "Botola"
    if "u20" in txt:
        return "U20"
    if "afcon" in txt:
        return "AFCON"
    if is_top5_league(row.get("league", "")):
        return "Top Europe"
    if any(x in txt for x in ["eredivisie", "primeira", "portugal", "belgium", "championship"]):
        return "Europe 2"
    return "Other"


def context_cap(row, has_real_kpi=False, has_value=False):
    ctx = dataset_context(row)
    if ctx == "Botola":
        return 72 if has_real_kpi or has_value else 62
    if ctx == "U20":
        return 76 if has_real_kpi or has_value else 66
    if ctx == "AFCON":
        return 82 if has_real_kpi or has_value else 74
    if ctx == "Top Europe":
        return 88 if has_value or has_real_kpi else 76
    if ctx == "Europe 2":
        return 84 if has_value or has_real_kpi else 72
    return 80 if has_value or has_real_kpi else 68


def compute_scouting_score(row):
    """Realistic internal scouting score.
    Scale philosophy:
    50-62 = follow-up / local level
    63-72 = solid pro / local top / prospect
    73-80 = national team watchlist
    81-84 = national team level
    85-88 = elite Morocco level
    """
    mv = normalize_market_value(row.get("market_value", 0))
    minutes = float(row.get("minutes", 0) or 0)
    goals = float(row.get("goals", 0) or 0)
    xg = float(row.get("xg", 0) or 0)
    age = row.get("age", np.nan)
    group = row.get("position", "Unknown")
    league = str(row.get("league", ""))
    team = str(row.get("team", ""))
    data_source = str(row.get("data_source", ""))

    has_real_kpi = (minutes >= 450) or (goals > 0) or (xg > 0) or ("Wyscout" in data_source) or ("Manual" in data_source)
    has_value = mv >= 1_000_000

    # Competition and club matter a lot, but never alone enough to create an elite score.
    comp = league_bonus(league)  # approx 3-10
    club = club_bonus(team)      # 0 or 4

    score = 38
    score += min(14, comp * 1.25)                    # league strength
    score += min(16, mv / 4_000_000)                 # market value, controlled
    score += min(10, minutes / 380)                  # minutes played
    score += min(7, goals * 0.35 + xg * 0.30)        # attacking production
    score += min(4, age_score(age) * 0.55)           # age profile
    score += min(4, club)                            # club prestige

    if group == "Attacker":
        score += 1.5
    elif group == "Midfielder":
        score += 1.2
    elif group == "Defender":
        score += 0.8
    elif group == "Goalkeeper":
        score += 0.5

    cap = context_cap(row, has_real_kpi=has_real_kpi, has_value=has_value)

    # Estimated-only players must stay conservative.
    if not has_real_kpi and not has_value:
        score = min(score, cap)

    return round(float(np.clip(score, 42, cap)), 1)


def compute_profile_ratings(row):
    score = float(row.get("scouting_score", 60) or 60)
    mv = normalize_market_value(row.get("market_value", 0))
    minutes = float(row.get("minutes", 0) or 0)
    goals = float(row.get("goals", 0) or 0)
    xg = float(row.get("xg", 0) or 0)
    age = row.get("age", np.nan)
    group = row.get("position", "Unknown")
    role = str(row.get("specific_role", ""))
    ctx = dataset_context(row)
    estimated = "estimated" in str(row.get("data_source", "")).lower()

    # More realistic sub-ratings. No 99s. No inflated Botola players.
    if group == "Attacker":
        technical = 46 + score * 0.36 + min(8, goals * 0.5 + xg * 0.35) + min(5, mv / 10_000_000)
        physical = 48 + score * 0.25 + min(10, minutes / 350)
    elif group == "Midfielder":
        technical = 48 + score * 0.34 + min(6, xg * 0.30) + min(5, mv / 11_000_000)
        physical = 48 + score * 0.24 + min(9, minutes / 380)
    elif group == "Defender":
        technical = 45 + score * 0.28 + min(6, minutes / 650) + min(4, mv / 15_000_000)
        physical = 52 + score * 0.28 + min(10, minutes / 360)
    elif group == "Goalkeeper":
        technical = 45 + score * 0.27 + min(8, minutes / 450) + min(4, mv / 15_000_000)
        physical = 50 + score * 0.25 + min(8, minutes / 430)
    else:
        technical = 45 + score * 0.30
        physical = 48 + score * 0.25

    try:
        age_f = float(age)
        if age_f <= 23:
            physical += 1.5
        elif age_f >= 30:
            physical -= min(6, (age_f - 30) * 0.9)
    except Exception:
        age_f = np.nan

    # Potential is mostly age + level. Older players cannot have high potential.
    potential = potential_from_age(age) + min(3, mv / 25_000_000) + max(0, (score - 78) * 0.08)

    # Context caps: realistic ceilings by level.
    if ctx == "Botola":
        cap_t, cap_ph, cap_pot, cap_overall = (68, 74, 78, 72) if not estimated else (64, 70, 74, 64)
    elif ctx == "U20":
        cap_t, cap_ph, cap_pot, cap_overall = (74, 78, 90, 76)
    elif ctx == "AFCON":
        cap_t, cap_ph, cap_pot, cap_overall = (82, 84, 86, 82)
    elif ctx == "Top Europe":
        cap_t, cap_ph, cap_pot, cap_overall = (88, 88, 90, 88)
    elif ctx == "Europe 2":
        cap_t, cap_ph, cap_pot, cap_overall = (84, 84, 88, 84)
    else:
        cap_t, cap_ph, cap_pot, cap_overall = (80, 82, 86, 80)

    # Position-specific caps
    if group == "Defender":
        cap_t = min(cap_t, 80)
    if group == "Goalkeeper":
        cap_t = min(cap_t, 78)

    technical = int(round(np.clip(technical, 38, cap_t)))
    physical = int(round(np.clip(physical, 38, cap_ph)))
    potential = int(round(np.clip(potential, 45, cap_pot)))

    overall = int(round(technical * 0.35 + physical * 0.25 + potential * 0.20 + score * 0.20))
    overall = int(np.clip(overall, 40, cap_overall))
    return technical, physical, potential, overall


def radar_values(row):
    technical, physical, potential, overall = compute_profile_ratings(row)
    group = row.get("position", "Unknown")
    role = str(row.get("specific_role", ""))
    score = float(row.get("scouting_score", overall) or overall)
    goals = float(row.get("goals", 0) or 0)
    xg = float(row.get("xg", 0) or 0)

    if group == "Defender":
        defending = min(88, technical + 8)
        shooting = max(32, technical - 23)
        passing = min(82, technical + 4)
        dribbling = max(38, technical - 5)
        pace = min(86, physical + (3 if role in ["RB", "LB", "LWB", "RWB"] else 0))
    elif group == "Attacker":
        defending = max(34, technical - 24)
        shooting = min(88, technical + 3 + min(3, goals * 0.15 + xg * 0.10))
        passing = min(86, technical + (2 if role in ["CF", "CAM", "LW", "RW"] else 0))
        dribbling = min(88, technical + (4 if role in ["LW", "RW", "CAM"] else 2))
        pace = min(88, physical + (4 if role in ["LW", "RW"] else 1))
    elif group == "Midfielder":
        defending = max(42, technical - (2 if role in ["DM", "CM"] else 10))
        shooting = max(42, technical - (4 if role in ["CAM", "AM"] else 9))
        passing = min(88, technical + 5)
        dribbling = min(86, technical + (3 if role in ["CAM", "AM"] else 1))
        pace = min(84, physical + 1)
    elif group == "Goalkeeper":
        defending = min(86, technical + 6)
        shooting = 25
        passing = min(78, technical + 2)
        dribbling = max(35, technical - 10)
        pace = min(76, physical)
    else:
        defending = max(40, technical - 4)
        shooting = max(35, technical - 10)
        passing = technical
        dribbling = max(40, technical - 3)
        pace = physical

    return {
        "Ritmo": int(np.clip(pace, 0, 100)),
        "Regate": int(np.clip(dribbling, 0, 100)),
        "Pase": int(np.clip(passing, 0, 100)),
        "Tiro": int(np.clip(shooting, 0, 100)),
        "Defensa": int(np.clip(defending, 0, 100)),
        "Físico": int(np.clip(physical, 0, 100)),
    }

