def source_priority(value):
    value = str(value).lower()
    if "manual" in value:
        return 4
    if "rabie" in value:
        return 3
    if "estimated" in value:
        return 1
    return 2

def dataset_priority(value):
    value = strip_accents(str(value)).lower()
    if "europe" in value:
        return 4
    if "afcon" in value:
        return 3
    if "botola" in value:
        return 2
    if "u20" in value:
        return 1
    return 0

