def display_table(df, cols=None):
    if df is None or len(df) == 0:
        return pd.DataFrame()
    out = df.copy()
    if cols is not None:
        cols = [c for c in cols if c in out.columns]
        out = out[cols].copy()
    if "position" in out.columns:
        out["position"] = out["position"].map(POSITION_ES).fillna(out["position"])
    if "data_source" in out.columns:
        out["data_source"] = out["data_source"].map(SOURCE_ES).fillna(out["data_source"])
    if "status" in out.columns:
        out["status"] = out["status"].map(STATUS_ES).fillna(out["status"])
    if "market_value" in out.columns:
        out["market_value"] = out["market_value"].apply(lambda x: "-" if pd.isna(x) else f"€{int(x):,}")
    return out.rename(columns={c: SPANISH_COLUMNS.get(c, c) for c in out.columns})

